#!/usr/bin/env node
// Builds per-persona clip playlists from the value-tagged KERICONF26 clips.
// Reads  src/data/keri-clips.json (generated by fetch-clips)
// Writes src/data/keri-personas.json and docs/persona-clips.md
//
// Persona definitions mirror docs/persona-plan.md. Each persona lists the value
// tags that resonate with it; clips are scored by tag overlap (weighted by tag
// order), quote quality and duration, then the top picks are chosen with a
// speaker-diversity constraint so a reel is not a single talk.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const clipsPath = join(root, 'src/data/keri-clips.json');
const outJson = join(root, 'src/data/keri-personas.json');
const outMd = join(root, 'docs/persona-clips.md');

export const PERSONAS = [
  {
    id: 'ciso',
    name: 'Sarah — Enterprise CISO / Security Architect',
    message:
      'KERI assumes you will be breached and lets you recover: pre-rotated keys make stolen credentials dead on arrival, and everything is verifiable, not merely validated.',
    tags: ['SECUFIRST', 'FAULTTOL', 'OTHUNSAFE', 'ANTIFRAUD', 'VERNOTVAL', 'NOSHARSECR', 'ENTROPY'],
  },
  {
    id: 'regulator',
    name: 'Marcus — Regulator / Policy Maker / Legal Counsel',
    message:
      'KERI is the only identity layer that can model real-world legal authority — with recourse on identifiable peers — without a blockchain or a foreign trust anchor.',
    tags: ['LEGOVPOL', 'ORGID', 'RECOUPEERS', 'REALMPRAGM', '1PERSCONTR', 'CANMODELRW', 'PROVCONTXT'],
  },
  {
    id: 'developer',
    name: 'Dev — Software Engineer / Architect',
    message:
      'KERI already solved the problem you would otherwise bolt together from five libraries — persistent identifiers, verifiable event logs, delegation — vendor- and crypto-agnostic, like git for identity.',
    tags: ['HARPROB1ST', 'NOWSTACK', 'EASEOFUSE', 'AGNOSTIC', 'UNBROCHAIN', 'GRASPEASY', 'MATURITY'],
  },
  {
    id: 'business',
    name: 'Elena — Business Decision Maker / Product Executive',
    message:
      'Verifiable organizational credentials collapse onboarding and KYC from weeks to minutes, cut fraud losses structurally, and run at global scale on infrastructure you already have.',
    tags: ['BIZEFFCASE', 'ATSCALE', 'ECONINFEA', 'EASEOFUSE', 'INFRASURF', 'MARKETPEN'],
  },
  {
    id: 'ssi-skeptic',
    name: 'Priya — SSI / Digital-Identity Community Skeptic',
    message:
      'Judge the tradespace, not the tribe: KERI is the only design that gets persistent identifiers without a ledger, and it bridges to the DID world instead of replacing it.',
    tags: ['VERNOTVAL', 'MINIMSUFFI', 'CANMODELRW', 'SPACTRILL', 'GRALIFCONF', 'NOSHARSECR', 'OTHUNSAFE'],
  },
  {
    id: 'end-user',
    name: 'Alex — End User / Privacy Advocate',
    message:
      'Your identity should belong to you for life — no usernames, no passwords, no platform that can delete you, and recourse when data about you is wrong.',
    tags: ['1PERSCONTR', 'SAFETY', 'RECOUPEERS', 'GRALIFCONF', 'INCLUSIVE', 'COMMUNEDU', 'PERPETUAL'],
  },
];

const CLIPS_PER_PERSONA = 5;
const MAX_PER_SPEAKER = 2;

function scoreClip(clip, tags) {
  let score = 0;
  for (const t of clip.tags || []) {
    const idx = tags.indexOf(t);
    // Earlier tags in the persona list matter more.
    if (idx >= 0) score += 10 + (tags.length - idx);
  }
  if (score === 0) return 0;
  const dur = (clip.end ?? clip.start + 60) - clip.start;
  if (dur >= 25 && dur <= 150) score += 6;
  else if (dur > 300) score -= 8;
  const q = (clip.quote || '').length;
  if (q > 60) score += 4;
  else if (q < 20) score -= 3;
  return score;
}

function pickClips(clips, persona) {
  const scored = clips
    .map((c) => ({ clip: c, score: scoreClip(c, persona.tags) }))
    .filter((s) => s.score > 0)
    .sort((a, b) => b.score - a.score);
  const picked = [];
  const perSpeaker = new Map();
  for (const { clip } of scored) {
    if (picked.length >= CLIPS_PER_PERSONA) break;
    const n = perSpeaker.get(clip.speaker) || 0;
    if (n >= MAX_PER_SPEAKER) continue;
    // Avoid overlapping segments from the same talk.
    if (picked.some((p) => p.videoId === clip.videoId && Math.abs(p.start - clip.start) < 90)) continue;
    perSpeaker.set(clip.speaker, n + 1);
    picked.push(clip);
  }
  return picked;
}

function fmtTime(s) {
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = Math.floor(s % 60);
  return (h ? [h, m, sec] : [m, sec]).map((x, i) => (i ? String(x).padStart(2, '0') : String(x))).join(':');
}

function main() {
  const data = JSON.parse(readFileSync(clipsPath, 'utf8'));
  const galleryUrl = data.meta?.galleryUrl || 'https://keri.foundation/confs/2026/videos/';

  const personas = PERSONAS.map((p) => ({
    ...p,
    clips: pickClips(data.clips, p).map((c) => ({
      ...c,
      url: `${galleryUrl}#${c.videoId}&t=${c.start}&e=${c.end}`,
    })),
  }));

  mkdirSync(dirname(outJson), { recursive: true });
  writeFileSync(
    outJson,
    JSON.stringify(
      {
        meta: {
          generated: new Date().toISOString().slice(0, 10),
          galleryUrl,
          notes: 'Per-persona clip playlists generated by scripts/build-personas.mjs from keri-clips.json. See docs/persona-plan.md.',
        },
        personas,
      },
      null,
      2,
    ) + '\n',
  );

  const md = ['# Persona clip reels', '', `Generated from the KERICONF26 value-tagged clips (${data.clips.length} segments). Each link opens the [video gallery](${galleryUrl}) at the exact moment and stops at the end of the clip. Persona rationale: [persona-plan.md](./persona-plan.md).`, ''];
  for (const p of personas) {
    md.push(`## ${p.name}`, '', `> ${p.message}`, '', `Value tags: ${p.tags.map((t) => `\`${t}\``).join(', ')}`, '');
    for (const c of p.clips) {
      md.push(`- [${fmtTime(c.start)}–${fmtTime(c.end)} · ${c.speaker} — ${c.talk}](${c.url})`);
      md.push(`  “${c.quote}” — tags: ${c.tags.join(', ')}`);
    }
    md.push('');
  }
  mkdirSync(dirname(outMd), { recursive: true });
  writeFileSync(outMd, md.join('\n') + '\n');

  for (const p of personas) {
    console.log(`${p.id}: ${p.clips.length} clips, speakers: ${[...new Set(p.clips.map((c) => c.speaker))].join(', ')}`);
  }
  console.log(`\nWrote ${outJson}\nWrote ${outMd}`);
}

main();
